1	import fs from 'node:fs';
2	import path from 'node:path';
3	import crypto from 'node:crypto';
4	import { spawnSync } from 'node:child_process';
5	import { fileURLToPath } from 'node:url';
6	export const phase = path.dirname(fileURLToPath(import.meta.url));
7	export const root = path.dirname(phase);
8	export const project = path.join(root, 'works/铜桥来信');
9	export const sha = b => crypto.createHash('sha256').update(b).digest('hex');
10	export const read = f => fs.readFileSync(f, 'utf8');
11	export const json = f => JSON.parse(read(f));
12	export function put(f, x) { fs.mkdirSync(path.dirname(f), { recursive: true }); fs.writeFileSync(f, Buffer.isBuffer(x) || typeof x === 'string' ? x : JSON.stringify(x, null, 2) + '\n', { flag: 'wx' }); }
13	export const state = (p = project) => json(path.join(p, '.writer/state.json'));
14	export const output = label => json(path.join(root, 'commands', 'native-two-' + label, 'stdout.raw.txt'));
15	export function run(label, args, p = project, token) {
16	  const argv = [path.join(root, 'capture.mjs'), 'native-two-' + label, 'node', 'bin/ai-writer.mjs', ...args, '--project', p, ...(token ? ['--revision-token', token] : [])];
17	  const result = spawnSync('node', argv, { cwd: 'D:/work/other/ai-writer', encoding: 'utf8', windowsHide: true, maxBuffer: 64 * 1024 * 1024 });
18	  process.stdout.write(result.stdout); process.stderr.write(result.stderr);
19	  if (result.status !== 0) throw Error('CLI exit ' + result.status + ': ' + label);
20	  return output(label);
21	}
22	export function input(name, x) { const f = path.join(phase, 'inputs', name + '.json'); put(f, x); return f; }
23	export function fingerprints(p = project) {
24	  const s = state(p);
25	  return { revision: s.revision, state_sha256: sha(fs.readFileSync(path.join(p, '.writer/state.json'))), schema_version: s.schema_version,
26	    units: s.units.map(u => ({ unit: u.unit, draft: u.draft, actual_sha256: sha(fs.readFileSync(path.join(p, u.draft))), registered_sha256: u.sha256, source_hashes: u.source_hashes, source_bindings: u.source_bindings })) };
27	}
28	export function bundle(name, p, refs) {
29	  let out = '# 实际文件阅读副本\n\n';
30	  for (const ref of [...new Set(refs)]) { const b = fs.readFileSync(path.join(p, ref)); out += `## ${ref}\n\nSHA256=${sha(b)}\n\n${b.toString('utf8')}\n\n`; }
31	  put(path.join(phase, 'readings', name + '.md'), out);
32	}
33	if (process.argv[2] === 'snapshot-start') {
34	  const s = state();
35	  put(path.join(phase, 'parent-before-body-fingerprints.json'), fingerprints());
36	  put(path.join(phase, 'parent-start-state.raw.json'), fs.readFileSync(path.join(project, '.writer/state.json')));
37	  put(path.join(phase, 'parent-start-tracking.json'), { units: s.units, snapshot: s.snapshot, sources: s.sources, governance: s.governance });
38	  bundle('parent-six-original', project, s.units.map(u => u.draft));
39	  for (const u of s.units) put(path.join(phase, 'original', u.draft), fs.readFileSync(path.join(project, u.draft)));
40	  const h = json(path.join(root, 'handoff.json'));
41	  const refs = [...new Set(s.units.flatMap(u => Object.keys(u.source_hashes)).filter(r => !['writer.json', '.writer/state.json'].includes(r) && !r.startsWith('正文/')))];
42	  bundle('old-consumed-inputs', project, [...refs, '研究/测试授权原话.md', '审查/独立修订1-6-复核.md', '审查/规则v2-第7章起-影响实读.md', ...Object.values(h.versions).map(v => v.object_ref)]);
43	  console.log(JSON.stringify({ phase, revision: s.revision, units: s.units.length }));
44	}
