nit":2,"draft":"正文/0002-两枚押钱.md","sha256":"e96be51cb52bd8fb6c436dc9b29ae8fed75a8120e8d087c0d2b5906d7486f828","line":13,"quote":"写明“收押三枚，归凭退还”。"},{"unit":3,"draft":"正文/0003-缺掉的一角.md","sha256":"2632f35bbe947ef9f7c5873104952f0e126cc9616df7af84bc8298b5b23fa880","line":27,"quote":"铜片还没算归档，收条上的三枚押钱也仍在柜面等着结清。"},{"unit":5,"draft":"正文/0005-旧印归柜.md","sha256":"b92469632b69481ab3aa1bfb0dc2540ff987f2d2b3bf748be4683ef83c9a6e8d","line":23,"quote":"从原借验号木格取出三枚押钱，平放在阿禾掌心，写下“三枚已退”。"},{"unit":5,"draft":"正文/0005-旧印归柜.md","sha256":"b92469632b69481ab3aa1bfb0dc2540ff987f2d2b3bf748be4683ef83c9a6e8d","line":23,"quote":"她数过，正好三枚，穿回钱绳。"},{"unit":5,"draft":"正文/0005-旧印归柜.md","sha256":"b92469632b69481ab3aa1bfb0dc2540ff987f2d2b3bf748be4683ef83c9a6e8d","line":23,"quote":"两枚钱的孔边原先洗得亮，如今沾了木格里的细灰；另一枚孔里还带着黑垢。"},{"unit":6,"draft":"正文/0006-信纸背面.md","sha256":"e27b5d5405cce82fb3d08e9dbac0b575d9d7e5ab665485d5a8a61ecf17dd3960","line":3,"quote":"把退回的三枚钱放进米缸旁的小碟。"}],"introduced_unit":2,"updated_unit":6}},{"kind":"unit","unit":1,"summary":"阿禾拆母亲旧棉袄发现铜片和‘桥头问信’纸条，凭折耳浅痕铜凭向周叔问信；旧簿记母亲名字为候，约次晨交两枚押钱借验。铜片未交柜，仍在阿禾贴身衣袋。","draft":"正文/0001-铜片的耳.md","sha256":"74f64a83a6b2f63893c5fa461be7d3074f006f25c22ae3029d63c067da0d3176"},{"kind":"unit","unit":2,"summary":"次晨阿禾按昨夜报价备两枚，柜前见新告示并经周叔当面说明，另添一枚，实缴三枚并取得三枚收条。铜片经周叔白布验记后交回阿禾腰袋；两人带簿钥匙下坡，阿禾得知母亲曾来问信并缝过钥匙绳。","draft":"正文/0002-两枚押钱.md","sha256":"e96be51cb52bd8fb6c436dc9b29ae8fed75a8120e8d087c0d2b5906d7486f828"},{"kind":"unit","unit":3,"summary":"阿禾与周叔在旧库待核包见疑似母亲的水渍封套，右下缺角方印与旧页印样相近，不能判揭封或仿印。阿禾描旧页印样、获柳婆修过印匣的线索；铜片交周叔锁旧柜借验匣暂存，未归档未退款。本章收条仍为三枚，暂存不等于归档退款。","draft":"正文/0003-缺掉的一角.md","sha256":"2632f35bbe947ef9f7c5873104952f0e126cc9616df7af84bc8298b5b23fa880"},{"kind":"unit","unit":5,"summary":"三人开封旧印匣，以原印补角高差、软硬垫试印及字内短缺口对验旧页和封套，确认缺角来自旧印修补；查出迁柜九号误誊六号，根票姓名、铜片背号画样及姨母地址核领。铜片仍归周叔锁匣归档；回驿柜退三枚押钱并交未拆信，柳婆带回试纸。","draft":"正文/0005-旧印归柜.md","sha256":"b92469632b69481ab3aa1bfb0dc2540ff987f2d2b3bf748be4683ef83c9a6e8d"},{"kind":"unit","unit":6,"summary":"阿禾回家将退回三枚放小碟，记得铜片留柜。她拆迟信，读到两年前姨母应母亲托请寄来的鞋样与日常劝语，重新理解母亲。她夹好鞋样，在姨母信背写下请来吃饭的回信句，正文在本章停止。","draft":"正文/0006-信纸背面.md","sha256":"e27b5d5405cce82fb3d08e9dbac0b575d9d7e5ab665485d5a8a61ecf17dd3960"}],"total":8,"omitted":0,"note":"关键词定位，不代表已经阅读原文或语义检索完整"}}
